	{
		let isSign;
		if (peek() == '-') {
			isSign = true;
			get();
		}
		else isSign = false; 

		let result = get() - '0';
		while (peek() >= '0' && peek() <= '9')
			result = 10*result + (get() - '0');
		if (peek() == '.') {
			get(); // '.'
			let decpart = 0;
			let cnt = 1
			while (peek() >= '0' && peek() <= '9') {
				cnt = cnt * 10;
				decpart = 10*decpart + (get() - '0');
			}
			result = result + (decpart/cnt);
		}
		if (isSign)
			result = -result;
		return result;
	}

